// Drives real Chromium over sites generated by a built vados binary, for what
// the Rust tests can't see: layout, keyboard use, scripts and computed colours.
// The stylesheet is compiled from the README's list of Bulma modules, so this
// also proves that list is enough.
//
//   cargo build && npm ci && npx playwright-core install chromium && npm test
//
// VADOS names the binary (default: ../../target/debug/vados). BROWSER_PATH names
// a browser to use instead of Playwright's own.
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright-core";

const here = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(here, "../..");
const vados = path.resolve(process.env.VADOS ?? path.join(repo, "target/debug/vados"));
const work = fs.mkdtempSync(path.join(os.tmpdir(), "vados-browser-"));

const results = [];
const check = (name, passed, detail = "") => results.push({ name, passed, detail });

// --- Sites ---

function write(file, contents) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, typeof contents === "string" || Buffer.isBuffer(contents) ? contents : JSON.stringify(contents));
}

function compiledStylesheet() {
  const readme = fs.readFileSync(path.join(repo, "README.md"), "utf8");
  const modules = readme.match(/^@use "bulma\/sass\/.*$/gm);
  const entry = path.join(work, "bulma.scss");
  fs.writeFileSync(entry, modules.join("\n"));
  const output = path.join(work, "bulma.css");
  execFileSync(
    path.join(here, "node_modules/.bin/sass"),
    [`--load-path=${path.join(here, "node_modules")}`, "--quiet-deps", "--no-source-map", entry, output],
    { stdio: "inherit" },
  );
  return output;
}

function generate(name, files) {
  const root = path.join(work, name, "root");
  for (const [file, contents] of Object.entries(files)) {
    write(path.join(root, file), contents);
  }
  write(path.join(root, "static/bulma.css"), fs.readFileSync(stylesheet));
  fs.mkdirSync(path.join(work, name, "img"), { recursive: true });
  const destination = path.join(work, name, "public");
  execFileSync(
    vados,
    ["generate", "--source", root, "--img-source", path.join(work, name, "img"), "--destination", destination, "--check-links"],
    { stdio: "pipe" },
  );
  return destination;
}

