// --- A server resolving addresses like a static host, with a strict policy ---

function serve(root, { failFirstIndex = false } = {}) {
  const requests = [];
  let failIndex = failFirstIndex;
  const types = { ".css": "text/css", ".js": "text/javascript", ".mjs": "text/javascript", ".html": "text/html", ".json": "application/json" };
  const server = http.createServer((request, response) => {
    const address = new URL(request.url, "http://x").pathname;
    requests.push(address);
    if (address === "/search-index.json" && failIndex) {
      failIndex = false;
      response.writeHead(500);
      return response.end();
    }
    const candidates = address === "/" ? ["index.html"] : [`${address}.html`, address];
    const file = candidates.map((c) => path.join(root, c)).find((c) => fs.existsSync(c) && fs.statSync(c).isFile());
    if (!file) {
      response.writeHead(404);
      return response.end();
    }
    response.writeHead(200, {
      "content-type": types[path.extname(file)] ?? "text/plain",
      "content-security-policy": "default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self'",
    });
    response.end(fs.readFileSync(file));
  });
  return new Promise((resolve) => server.listen(0, () => resolve({ url: `http://localhost:${server.address().port}`, requests, close: () => server.close() })));
}

// --- Navigation ---

async function checkMenuAtEverySize(browser, base) {
  for (const width of [1024, 1216, 1440]) {
    for (const textSize of [100, 200]) {
      const label = `${width}px at ${textSize}%`;
      const context = await browser.newContext({ viewport: { width, height: 800 } });
      const page = await context.newPage();
      const errors = [];
      page.on("pageerror", (e) => errors.push(e.message));
      await page.goto(`${base}/vandaag/sub1`);
      if (textSize === 200) {
        await page.addStyleTag({ content: "html{font-size:200%}" });
      }
      await page.waitForTimeout(150);
      const burger = await page.evaluate(() => getComputedStyle(document.getElementById("burger-menu")).display !== "none");
      if (burger) {
        await page.click("#burger-menu");
        await page.waitForTimeout(50);
      }
      const layout = await page.evaluate(() => {
        const screen = document.documentElement.clientWidth;
        const items = [...document.querySelectorAll("#flex-main-menu>*")];
        const out = items.filter((e) => {
          const box = e.getBoundingClientRect();
          return box.right > screen + 1 || box.width === 0;
        });
        return {
          out: out.map((e) => e.textContent.trim()),
          bar: document.getElementById("nav-bar").offsetHeight,
          top: document.querySelector("main").getBoundingClientRect().top,
        };
      });
      check(`${label}: every item is on screen`, layout.out.length === 0, JSON.stringify(layout));
      if (!burger) {
        check(`${label}: the page clears the bar`, layout.top >= layout.bar - 1, JSON.stringify(layout));
      }
      const buttons = page.locator(".nav-disclosure");
      for (let i = 0; i < (await buttons.count()); i++) {
        // Clicking also proves nothing covers the button, such as social icons.
        await buttons.nth(i).click({ timeout: 4000 });
        await page.waitForTimeout(30);
        const box = await page.evaluate((n) => {
          const list = document.querySelectorAll(".navbar-dropdown")[n];
          const r = list.getBoundingClientRect();
          return { left: r.left, right: r.right, bottom: r.bottom, height: innerHeight, width: document.documentElement.clientWidth, hidden: list.hidden };
        }, i);
        const onScreen = !box.hidden && box.left >= -1 && box.right <= box.width + 1 && (burger || box.bottom <= box.height + 1);
        check(`${label}: dropdown ${i} stays on screen`, onScreen, JSON.stringify(box));
        await page.keyboard.press("Escape");
      }
      check(`${label}: no script errors`, errors.length === 0, errors.join());
      await context.close();
    }
  }
}

async function checkMenuKeyboard(browser, base) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await context.newPage();
  await page.goto(base + "/");
  const button = page.locator(".nav-disclosure").first();
  const expanded = () => button.getAttribute("aria-expanded");
  check("the button shows with a script", await button.isVisible());
  check("the button's name is translated", (await button.getAttribute("aria-label")) === "Subpagina's van Vandaag");
  check("the script takes over from hover", (await page.locator(".is-hoverable").count()) === 0);
  await button.focus();
  check("children aren't reachable while closed", await page.locator("#nav-subpages-0 a").first().isHidden());
  await page.keyboard.press("Space");
  check("Space opens", (await expanded()) === "true");
  await page.keyboard.press("Tab");
  check("Tab reaches a child", await page.evaluate(() => document.activeElement.closest("#nav-subpages-0") !== null));
  await page.keyboard.press("Escape");
  check("Escape closes and returns focus", (await expanded()) === "false" && (await button.evaluate((e) => e === document.activeElement)));
  await button.click();
  await page.locator(".nav-disclosure").nth(1).click();
  check("opening one closes the others", (await expanded()) === "false");
  await page.mouse.click(600, 500);
  check("a click elsewhere closes it", (await page.locator(".nav-disclosure[aria-expanded=true]").count()) === 0);
  await button.click();
  await page.locator("#nav-site-title").focus();
  await page.waitForTimeout(20);
  check("focus leaving closes it", (await expanded()) === "false");
  check("a long list is cut short with a link", (await page.locator("#nav-subpages-0 .nav-more").count()) === 1 && (await page.locator("#nav-subpages-0 a").count()) === 5);
  await page.hover("[data-nav-disclosure]");
  check("hover no longer opens it", await page.locator("#nav-subpages-0 a").first().isHidden());
  check("an unknown icon leaves no box", (await page.locator("#flex-main-menu .icon:empty").count()) === 0);
  await context.close();

  const phone = await browser.newContext({ viewport: { width: 320, height: 700 } });
  const small = await phone.newPage();
  await small.goto(base + "/");
  await small.click("#burger-menu");
  await small.locator(".nav-disclosure").first().focus();
  await small.keyboard.press("Enter");
  check("320px: a list opens", await small.locator("#nav-subpages-0 a").first().isVisible());
  await small.keyboard.press("Escape");
  await small.keyboard.press("Escape");
  check("320px: Escape closes the burger menu", (await small.locator("#burger-menu").getAttribute("aria-expanded")) === "false" && (await small.evaluate(() => document.activeElement.id === "burger-menu")));
  await phone.close();

  const noScript = await browser.newContext({ viewport: { width: 1280, height: 800 }, javaScriptEnabled: false });
  const plain = await noScript.newPage();
  await plain.goto(base + "/");
  check("no script: the button stays hidden", await plain.locator(".nav-disclosure").first().isHidden());
  await plain.hover("[data-nav-disclosure]");
  check("no script: hover opens the list", await plain.locator("#nav-subpages-0 a").first().isVisible());
  await noScript.close();
}

// --- Contrast ---

function contrast(a, b) {
  const luminance = (rgb) => {
    const [r, g, blue] = rgb.map((v) => {
      const c = v / 255;
      return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
    });
    return 0.2126 * r + 0.7152 * g + 0.0722 * blue;
  };
  const [light, dark] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (light + 0.05) / (dark + 0.05);
}

async function checkContrast(browser) {
  for (const color of ["White", "Black", "Light", "Dark", "Primary", "Link", "Info", "Success", "Warning", "Danger"]) {
    const server = await serve(colourSite(color));
    for (const colorScheme of ["light", "dark"]) {
      const context = await browser.newContext({ colorScheme, viewport: { width: 1280, height: 700 } });
      const page = await context.newPage();
      await page.goto(`${server.url}/sec/kid`);
      // Measured mid-transition, a colour is still on its way from black.
      await page.addStyleTag({ content: "*{transition:none!important}" });
      await page.waitForTimeout(50);
      const colours = await page.evaluate(() => {
        const rgb = (value) => {
          const parts = value.match(/[\d.]+/g).map(Number);
          return value.startsWith("color(") ? parts.slice(0, 3).map((v) => v * 255) : parts.slice(0, 3);
        };
        const color = (element) => rgb(getComputedStyle(element).color);
        const list = document.querySelector(".navbar-dropdown");
        list.hidden = false;
        list.style.display = "block";
        const child = list.querySelector("a.is-active");
        return {
          bar: rgb(getComputedStyle(document.getElementById("nav-bar")).backgroundColor),
          item: color(document.querySelector("#flex-main-menu>a.navbar-item")),
          active: color(document.querySelector(".navbar-link.is-active")),
          child: color(child),
          childBackground: rgb(getComputedStyle(child).backgroundColor),
          socials: [...document.querySelectorAll("#nav-socials a")].map((link) => ({
            label: link.getAttribute("aria-label"),
            colour: color(link.querySelector(".icon")),
            hasSvg: !!link.querySelector("svg path"),
            rel: link.getAttribute("rel"),
          })),
        };
      });
      const label = `${color} navbar in ${colorScheme}`;
      for (const [name, ratio] of [
        ["item", contrast(colours.item, colours.bar)],
        ["active item", contrast(colours.active, colours.bar)],
        ["active child", contrast(colours.child, colours.childBackground)],
      ]) {
        check(`${label}: ${name} reaches 4.5:1`, ratio >= 4.5, ratio.toFixed(2));
      }
      check(`${label}: every new social provider renders`, colours.socials.length === socialAddresses.length);
      for (const social of colours.socials) {
        const ratio = contrast(social.colour, colours.bar);
        check(`${label}: ${social.label} override reaches 3:1`, ratio >= 3, ratio.toFixed(2));
        check(`${label}: ${social.label} has an SVG and rel=me`, social.hasSvg && social.rel === "me noopener");
      }
      await context.close();
    }
    server.close();
  }
}

// --- Search, agenda and the spare tile, under a strict policy ---

async function checkFeatures(browser, root) {
  const server = await serve(root, { failFirstIndex: true });
  const base = server.url;
  const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  page.on("console", (m) => {
    const expected = m.text().includes("500") || m.location().url.endsWith("/favicon.ico");
    if (m.type() === "error" && !expected) {
      errors.push(m.text());
    }
  });
  const statusIs = (text) => page.waitForFunction((t) => document.getElementById("search-status").textContent === t, text);

  await page.goto(base + "/");
  check("the menu has a search entry", (await page.locator('#flex-main-menu a[href="/search"]').count()) === 1);
  check("the spare tile fills the cell", await page.locator("#spare-tile").isVisible());

  await page.goto(base + "/search");
  check("no index is fetched before searching", !server.requests.includes("/search-index.json"));
  check("the form shows with a script", await page.locator("#search-form").isVisible());
  check("the no-script note goes away", await page.locator("#search-no-script").isHidden());
  await page.fill("#search-input", "   ");
  await page.keyboard.press("Enter");
  await page.waitForTimeout(100);
  check("a blank search asks for nothing", !server.requests.includes("/search-index.json"));
  await page.fill("#search-input", "cafe KOFFIE");
  await page.keyboard.press("Enter");
  await statusIs("De zoekfunctie kon niet worden geladen. Probeer het opnieuw.");
  check("a failed download says so", true);
  await page.keyboard.press("Enter");
  await statusIs("1 resultaat");
  check("trying again finds it, ignoring accents and case", true);
  check("a title is text, not markup", (await page.textContent("#search-results a")).includes("<b>bar</b>"));
  check("focus stays in the input", await page.evaluate(() => document.activeElement.id === "search-input"));
  check("the status is announced", (await page.getAttribute("#search-status", "role")) === "status");
  check("the address keeps the search", page.url().includes("q=cafe"));
  await page.goto(page.url());
  await statusIs("1 resultaat");
  check("coming back restores it", (await page.inputValue("#search-input")) === "cafe KOFFIE");
  await page.fill("#search-input", "geenresultaat");
  await page.keyboard.press("Enter");
  await statusIs("Niets gevonden.");
  check("no results says so", true);

  await page.goto(base + "/agenda");
  check("an event that ended is hidden", await page.locator('li:has-text("Voorbij")').isHidden());
  check("a coming event shows", await page.locator('li:has-text("Straks")').isVisible());
  const toggle = page.locator("[data-agenda-toggle]");
  check("the toggle shows", await toggle.isVisible());
  await toggle.click();
  check("the toggle reveals past events", await page.locator('li:has-text("Voorbij")').isVisible());
  check("the toggle says what it does next", (await toggle.textContent()).includes("verbergen"));
  check("no errors under a strict policy", errors.length === 0, errors.join(" | "));
  await context.close();

  const phone = await browser.newContext({ viewport: { width: 400, height: 800 } });
  const small = await phone.newPage();
  await small.goto(base + "/");
  check("the spare tile is hidden on a phone", await small.locator("#spare-tile").isHidden());
  await phone.close();

  const noScript = await browser.newContext({ viewport: { width: 1280, height: 800 }, javaScriptEnabled: false });
  const plain = await noScript.newPage();
  await plain.goto(base + "/search");
  check("no script: no form that does nothing", await plain.locator("#search-form").isHidden());
  check("no script: the page says why", (await plain.content()).includes("JavaScript"));
  await plain.goto(base + "/agenda");
  check("no script: every event shows", await plain.locator('li:has-text("Voorbij")').isVisible());
  check("no script: no dead toggle", await plain.locator("[data-agenda-toggle]").isHidden());
  await noScript.close();
  server.close();
}

async function checkSearchScriptFailing(browser, root) {
  const server = await serve(root);
  const page = await browser.newPage();
  await page.route("**/vados-search.js", (route) => route.abort());
  await page.goto(`${server.url}/search`);
  check("search script failing: the page says why", await page.locator("#search-no-script").isVisible());
  await page.close();
  server.close();
}

